 function ReferenceHeader(){return <header className="reference-header"><svg viewBox="0 0 1536 277" preserveAspectRatio="none" aria-hidden="true"><defs><linearGradient id="header-gold" x1="0" y1="0" x2="0.28" y2="1"><stop stopColor="#81501a"/><stop offset=".12" stopColor="#b8822d"/><stop offset=".24" stopColor="#f2d38a"/><stop offset=".32" stopColor="#fff5cd"/><stop offset=".39" stopColor="#d9ac54"/><stop offset=".49" stopColor="#9a611b"/><stop offset=".57" stopColor="#c89238"/><stop offset=".69" stopColor="#ffe8a5"/><stop offset=".76" stopColor="#fff7d8"/><stop offset=".83" stopColor="#d6a348"/><stop offset=".94" stopColor="#996020"/><stop offset="1" stopColor="#e7bc66"/></linearGradient></defs><path d="M0 0H1536V137H788C751 137 738 128 717 108C704 95 695 85 682 82C581 109 489 133 397 177L375 214C337 260 303 273 244 273H70C36 273 13 269 0 262Z" fill="white" stroke="url(#header-gold)" strokeWidth="4"/><path d="M397 177C506 106 576 127 633 61C659 30 676 9 701 0H1100C944 17 844 42 745 66C600 102 502 127 397 177Z" fill="url(#header-gold)"/><path d="M438 153C591 111 664 38 738 0M538 119C703 72 838 34 980 0" fill="none" stroke="#fff0bd" strokeWidth="2"/></svg><a href="#/" className="reference-logo"><img src={ASSETS.logo} alt="Недвижими имоти Недвижими Имоти Надежда"/></a><nav aria-label="Основна навигация"><button onClick={()=>{setTransaction('sale');selectCity(city)}}>За продажба</button><button onClick={()=>{setTransaction('rent');selectCity(city)}}>Под наем</button><button onClick={()=>setModal('about')}>За нас</button><button onClick={()=>openAccount('profile')} aria-label="Моят профил"><Icon name="user"/></button></nav></header>}
