 const [route,setRoute]=useState(location.hash.slice(1)||'/');const [modal,setModal]=useState(null);const [modalFullscreen,setModalFullscreen]=useState(false);const [neighborhoodsFull,setNeighborhoodsFull]=useState(false);const [toast,setToast]=useState('');const [favorites,setFavorites]=useState(()=>readStore('ildjia-favorites',[]));const [profile,setProfile]=useState(()=>readStore('ildjia-profile',{role:'Купувач',name:'',email:''}));const [accountTab,setAccountTab]=useState('profile');const [contracts,setContracts]=useState(()=>readStore('ildjia-contracts',[]));const [selectedNeighborhood,setSelectedNeighborhood]=useState(()=>neighborhoods.find(n=>n.slug===ndLastSeg(location.hash.slice(1)))?.name||neighborhoods[0].name);const [transaction,setTransaction]=useState('sale');const [filters,setFilters]=useState({type:'Всички',price:'Без значение',area:'Без значение',min:'',max:'',types:[]});const [appliedFilters,setAppliedFilters]=useState(null);const [sort,setSort]=useState('new');const [listView,setListView]=useState(false);const [gallery,setGallery]=useState(0);const [expanded,setExpanded]=useState(false);const [favoriteNeighborhood,setFavoriteNeighborhood]=useState(false);
 const isHome=route==='/'||route==='/home';const isDetail=route.startsWith('/property');const activeProperty=properties.find(p=>String(p.id)===route.split('/')[2])||properties[0]||{id:'',name:'Няма публикувани имоти',title:'Няма публикувани имоти',price:0,area:0,rooms:0,baths:0,img:ASSETS.exterior,gallery:[],desc:''};useEffect(()=>{if(!isDetail||!activeProperty||!activeProperty.city)return;const c=cityCatalog.find(c=>c.name===activeProperty.city);if(c&&c.slug!==citySlug)setCitySlug(c.slug);if(activeProperty.hood&&ndLabel(activeProperty.hood)!==selectedNeighborhood)setSelectedNeighborhood(ndLabel(activeProperty.hood));setGallery(g=>g<(activeProperty.gallery||[]).length?g:0)},[isDetail,activeProperty&&activeProperty.id,activeProperty&&activeProperty.city,citySlug,selectedNeighborhood]);const galleryImages=(activeProperty.gallery&&activeProperty.gallery.length?activeProperty.gallery:[activeProperty.img||ASSETS.exterior]);const GN=galleryImages.length||1;
