 const openPlace=async name=>{setPlace(name);setDistance('Изчислява се разстоянието…');try{const lookup=async q=>{const response=await fetch('https://nominatim.openstreetmap.org/search?format=jsonv2&limit=1&q='+encodeURIComponent(q));const found=await response.json();if(!found?.length)throw new Error('not found');return found[0]};const [origin,destination]=await Promise.all([lookup(city.name+', България'),lookup(name+', област '+city.name+', България')]);const response=await fetch(`https://router.project-osrm.org/route/v1/driving/${origin.lon},${origin.lat};${destination.lon},${destination.lat}?overview=false`);const route=await response.json();if(!route.routes?.length)throw new Error('route unavailable');setDistance(Math.round(route.routes[0].distance/1000)+' км по път')}catch{setDistance('Разстоянието не е налично')}};
