 const preferenceInputs=form.querySelectorAll('input[name="preferences"]');preferenceInputs.forEach(input=>{if(text.toLocaleLowerCase('bg').includes(input.value.toLocaleLowerCase('bg')))input.checked=true});
 const areaLabel=pick([/^(?:площ|area)\s*[:：-]?\s*/i]);const areaValues=(areaLabel||text.match(/(?:площ|area)[^\d]{0,15}([\d.,]+(?:\s*[-–—]\s*[\d.,]+)?)/i)?.[1]||'').match(/[\d.,]+/g);if(areaValues?.length){set('areaMin',areaValues[0].replace(',','.'));if(areaValues[1])set('areaMax',areaValues[1].replace(',','.'))}
 const budgetLine=pick([/^(?:бюджет|цена|budget)\s*[:：-]?\s*/i]);const moneyValues=(budgetLine||text.match(/(?:бюджет|цена|budget)[^\d]{0,20}([\d. ]+(?:\s*[-–—]\s*[\d. ]+)?)/i)?.[1]||'').match(/[\d][\d .]*/g);if(moneyValues?.length){set('budgetMin',moneyValues.length>1?moneyValues[0].replace(/[ .]/g,''):'');set('budgetMax',moneyValues[moneyValues.length-1].replace(/[ .]/g,''))}
