 const handleAIFile=async file=>{if(!file)return;setAiAttachment(file.name);setAiMenu(false);if(file.type.startsWith('image/')){if(aiImage)URL.revokeObjectURL(aiImage);setAiImage(URL.createObjectURL(file));setAiScanning(true);try{if(!window.Tesseract){await new Promise((resolve,reject)=>{const s=document.createElement('script');s.src='https://cdn.jsdelivr.net/npm/tesseract.js@5.0.4/dist/tesseract.min.js';s.onload=resolve;s.onerror=reject;document.head.appendChild(s)})}const result=await window.Tesseract.recognize(file,'bul+eng');fillClientFromText(result.data.text)}catch(err){setToast('Неуспешно разчитане. Опитайте с по-ясна снимка.')}finally{setAiScanning(false)}}else if(file.type==='text/plain'||/\.(txt|csv)$/i.test(file.name)){try{const content=await file.text();const box=document.querySelector('.new-client-ai textarea');if(box)box.value=content;fillClientFromText(content)}catch{setToast('Файлът не може да бъде прочетен')}}else{setToast('Файлът е прикачен. За автоматично разчитане използвайте снимка или текстов файл.')}};
