class NDBoundary extends React.Component{constructor(p){super(p);this.state={err:null}}static getDerivedStateFromError(err){return{err}}componentDidCatch(err,info){try{console.error('[ND] render error',err,info&&info.componentStack)}catch(e){}}render(){if(!this.state.err)return this.props.children;return <div style={{minHeight:'100vh',display:'grid',placeItems:'center',padding:24,background:'#f7efe4'}}><div style={{maxWidth:520,textAlign:'center',padding:'34px 28px',borderRadius:26,border:'1.5px solid #e0b76b',background:'linear-gradient(160deg,#fffaf2,#f6e6cf)',boxShadow:'0 10px 30px #4c130c30,0 0 22px #e0b76b55'}}><img src="/mobile/crm/assets/logo.png" alt="Недвижими Имоти Надежда" style={{width:190,margin:'0 auto 14px'}}/><h2 style={{margin:'0 0 10px',color:'#6a001b',fontSize:26}}>Страницата не се зареди правилно</h2><p style={{margin:'0 0 20px',color:'#50191c',fontFamily:'Arial,sans-serif'}}>Моля, презаредете. Ако проблемът остане, обадете ни се на 0898 977 370.</p><button className="wine-button" style={{margin:'0 auto'}} onClick={()=>{location.hash='#/';location.reload()}}>Към началото</button> <button className="wine-button" style={{margin:'12px auto 0'}} onClick={()=>location.reload()}>Презареди</button><p style={{marginTop:16,fontSize:11,color:'#9a7a66',fontFamily:'Arial,sans-serif'}}>{String(this.state.err&&this.state.err.message||this.state.err).slice(0,160)}</p></div></div>}}
(function(){let root=null,done=false;const merge=()=>{properties.push(...(window.__ND_LISTINGS||[]).filter(p=>!properties.includes(p)));properties.forEach(p=>{if(!p.img)p.img=ASSETS.exterior})};const go=()=>{merge();if(!root)root=ReactDOM.createRoot(document.getElementById('root'));root.render(<NDBoundary><App/></NDBoundary>)};const t=setTimeout(()=>{if(!done)go()},6000);const fin=()=>{done=true;clearTimeout(t);go()};(window.__ND_READY||Promise.resolve()).then(fin,fin)})();
